using System;
using System.ComponentModel.Composition;
using System.Linq;
using System.Windows.Media;
using Microsoft.VisualStudio.Shell;
using Microsoft.VisualStudio.Text.Classification;
using Microsoft.VisualStudio.Text.Formatting;
using Microsoft.VisualStudio.Text.Tagging;
using SqlLense.Sql;

namespace SqlLense.Vsix.Editor
{
    /// <summary>
    /// One classification per alias color, created on demand because a query can have any number of
    /// aliases. Colors are generated by <see cref="SqlAliasPalette"/> for the current editor background
    /// and regenerated when the theme changes. They are not listed in Fonts and Colors.
    /// </summary>
    [Export(typeof(SqlAliasClassifications))]
    internal sealed class SqlAliasClassifications
    {
        private const string TextCategory = "text";

        private readonly IClassificationTypeRegistryService _registry;
        private readonly IClassificationFormatMapService _formatMaps;
        private readonly IEditorFormatMapService _editorFormatMaps;

        // Copy-on-write so taggers on other threads can read without locking; only the UI thread writes.
        private volatile ClassificationTag[] _tags = Array.Empty<ClassificationTag>();
        private IClassificationFormatMap? _formatMap;
        private IEditorFormatMap? _editorFormatMap;
        private SqlRgb _background;

        [ImportingConstructor]
        public SqlAliasClassifications(
            IClassificationTypeRegistryService registry,
            IClassificationFormatMapService formatMaps,
            IEditorFormatMapService editorFormatMaps)
        {
            _registry = registry;
            _formatMaps = formatMaps;
            _editorFormatMaps = editorFormatMaps;
        }

        /// <summary>
        /// The tag for alias color <paramref name="index"/>. New colors can only be registered on the UI
        /// thread (where the editor asks for tags when rendering); elsewhere this returns null for a color
        /// that does not exist yet, and the token keeps its normal identifier color.
        /// </summary>
        public IClassificationTag? GetTag(int index)
        {
            var tags = _tags;
            if (index < tags.Length)
            {
                return tags[index];
            }

            if (!ThreadHelper.CheckAccess())
            {
                return null;
            }

            EnsureInitialized();
            var grown = new ClassificationTag[Math.Max(index + 1, tags.Length * 2)];
            Array.Copy(tags, grown, tags.Length);

            var identifier = _registry.GetClassificationType(SqlClassificationDefinitions.Identifier);
            _formatMap!.BeginBatchUpdate();
            try
            {
                for (var i = tags.Length; i < grown.Length; i++)
                {
                    var name = "SqlLense.Alias." + i;
                    var type = _registry.GetClassificationType(name) ??
                        _registry.CreateClassificationType(name, identifier == null ? Array.Empty<IClassificationType>() : new[] { identifier });
                    _formatMap.AddExplicitTextProperties(type, Properties(i));
                    grown[i] = new ClassificationTag(type);
                }
            }
            finally
            {
                _formatMap.EndBatchUpdate();
            }

            _tags = grown;
            return grown[index];
        }

        /// <summary>The editor background for the current theme.</summary>
        public static SqlRgb GetBackground(IEditorFormatMap editorFormatMap)
        {
            var properties = editorFormatMap.GetProperties("TextView Background");
            var color = properties[EditorFormatDefinition.BackgroundColorId] as Color? ??
                (properties[EditorFormatDefinition.BackgroundBrushId] as SolidColorBrush)?.Color ??
                Colors.White;
            return new SqlRgb(color.R, color.G, color.B);
        }

        private void EnsureInitialized()
        {
            if (_formatMap != null)
            {
                return;
            }

            _formatMap = _formatMaps.GetClassificationFormatMap(TextCategory);
            _editorFormatMap = _editorFormatMaps.GetEditorFormatMap(TextCategory);
            _background = GetBackground(_editorFormatMap);
            _editorFormatMap.FormatMappingChanged += (_, e) =>
            {
                if (e.ChangedItems.Contains("TextView Background"))
                {
                    Recolor();
                }
            };
        }

        /// <summary>Theme changed: regenerate every color for the new background.</summary>
        private void Recolor()
        {
            var background = GetBackground(_editorFormatMap!);
            if (background.Equals(_background))
            {
                return;
            }

            _background = background;
            var tags = _tags;
            _formatMap!.BeginBatchUpdate();
            try
            {
                for (var i = 0; i < tags.Length; i++)
                {
                    _formatMap.SetExplicitTextProperties(tags[i].ClassificationType, Properties(i));
                }
            }
            finally
            {
                _formatMap.EndBatchUpdate();
            }
        }

        private TextFormattingRunProperties Properties(int index)
        {
            var rgb = SqlAliasPalette.GetColor(index, _background);
            var brush = new SolidColorBrush(Color.FromRgb(rgb.R, rgb.G, rgb.B));
            brush.Freeze();
            return TextFormattingRunProperties.CreateTextFormattingRunProperties().SetForegroundBrush(brush);
        }
    }
}
